def parse_mp0_dataset_code(data):
    if len(data) < 0x31:
        raise ValueError("Truncated data: insufficient length to read MP0 dataset code")

    # Read from offset 0x30 up to the NUL terminator
    start_offset = 0x30
    end_offset = data.find(b'\x00', start_offset)

    if end_offset == -1:
        # No NUL terminator found; read until the end of available data
        end_offset = len(data)

    raw_bytes = data[start_offset:end_offset]

    try:
        code = raw_bytes.decode('ascii')
        return code
    except UnicodeDecodeError:
        raise ValueError("Invalid ASCII characters found in MP0 dataset code field")

